// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  DownloadIcon,
  FileWarningIcon,
  ShieldAlertIcon,
  ShieldCheckIcon,
  XIcon,
} from 'lucide-react'

import {
  Bar,
  BrowserChrome,
  DemoStage,
  DockHeader,
  Toggle,
  type Build,
} from '@/app/demos/stage'

import { BLOCKED, CAPTIONS, COPY, DOWNLOAD, LOOKALIKE, RECENT, TRUSTED } from './script'

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  click,
  type,
  count,
  wait,
  cursorOut,
}) => {
  const navigate = (url: string, at?: string | number) =>
    tl.to(q('url-text'), { text: { value: url, delimiter: '' }, duration: 0.5, ease: 'none' }, at)

  const deflect = (index: number) => {
    const from = pos('url', 0.35, 0.5)
    const field = pos('page', 0.5, 0.42)
    const dot = q(`threat-${index}`)
    tl.set(dot, { x: from.x - 5, y: from.y - 5, opacity: 1, scale: 1 })
    tl.to(dot, { x: field.x - 5, y: field.y - 60, duration: 0.45, ease: 'power2.in' })
    tl.fromTo(
      q('field'),
      { scale: 0.7, opacity: 0.9 },
      { scale: 1.15, opacity: 0, duration: 0.7, ease: 'power2.out' },
      '>-0.05',
    )
    tl.to(
      dot,
      {
        x: field.x + 90,
        y: field.y - 150,
        scale: 0.4,
        opacity: 0,
        duration: 0.55,
        ease: 'power2.out',
      },
      '<',
    )
  }

  const blocked = (index: number, at?: string) => {
    count('stopped', index + 1, { from: index, at, duration: 0.5 })
    tl.fromTo(
      q(`recent-${index}`),
      { opacity: 0, x: 10 },
      { opacity: 1, x: 0, duration: 0.3, ease: 'power2.out' },
      '<',
    )
    tl.to(q('recent-empty'), { opacity: 0, duration: 0.15 }, '<')
    tl.fromTo(
      q('shield-ring'),
      { scale: 0.6, opacity: 0.9 },
      { scale: 1.8, opacity: 0, duration: 0.7, ease: 'power2.out' },
      '<',
    )
  }

  step(0)
  navigate(LOOKALIKE.url, 0.2)
  tl.to(q('scene-home'), { opacity: 0, duration: 0.2 })
  tl.to(q('scene-login'), { opacity: 1, duration: 0.25 }, '<')
  deflect(0)
  tl.fromTo(
    q('lookalike-card'),
    { opacity: 0, scale: 0.9, y: 8 },
    { opacity: 1, scale: 1, y: 0, duration: 0.35, ease: 'back.out(2)' },
    '<0.1',
  )
  tl.to(q('scrim'), { opacity: 1, duration: 0.3 }, '<')
  blocked(0, '<0.2')
  move('leave', { at: '+=0.3' })
  click('leave')
  tl.to([q('scene-login'), q('scrim'), q('lookalike-card')], { opacity: 0, duration: 0.25 }, '<0.1')
  navigate('about:blank', '<')

  step(1, '+=0.4')
  navigate(BLOCKED.url)
  deflect(1)
  tl.fromTo(
    q('scene-blocked'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power2.out' },
    '<0.1',
  )
  blocked(1, '<0.2')

  step(2, '+=1')
  tl.to(q('scene-blocked'), { opacity: 0, duration: 0.25 })
  navigate(DOWNLOAD.url, '<')
  tl.to(q('scene-download'), { opacity: 1, duration: 0.25 }, '>')
  tl.fromTo(
    q('chip'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'back.out(2)' },
    '+=0.3',
  )
  deflect(2)
  tl.fromTo(
    q('hold-card'),
    { opacity: 0, scale: 0.92, y: 8 },
    { opacity: 1, scale: 1, y: 0, duration: 0.35, ease: 'back.out(2)' },
    '<0.1',
  )
  blocked(2, '<0.2')
  move('delete', { at: '+=0.4' })
  click('delete')
  tl.to(q('hold-card'), { opacity: 0, scale: 0.95, duration: 0.25 }, '<0.1')
  tl.to(q('chip'), { opacity: 0, y: 6, duration: 0.25 }, '<')

  step(3, '+=0.4')
  move('trusted-input', { ax: 0.3 })
  click('trusted-input')
  type('trusted-text', TRUSTED, { speed: 0.035 })
  move('trusted-add')
  click('trusted-add')
  tl.to(q('trusted-text'), { text: '', duration: 0.1 }, '<0.1')
  tl.fromTo(
    q('trusted-chip'),
    { opacity: 0, scale: 0.7 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(2.5)' },
    '<',
  )
  tl.to(q('trusted-empty'), { opacity: 0, duration: 0.15 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)

  tl.set(qa('threat'), { opacity: 0 }, 0)
}

function Panel() {
  return (
    <div className="flex h-full flex-col">
      <DockHeader />
      <div className="flex flex-col gap-2.5 p-2.5">
        <div className="rounded-xl border border-line bg-white/[0.03] p-2.5">
          <div className="flex items-start justify-between gap-2">
            <div className="flex items-center gap-1.5">
              <span className="relative flex">
                <span
                  data-d="shield-ring"
                  className="absolute -inset-1 rounded-full border-2 border-[var(--accent)] opacity-0"
                />
                <ShieldCheckIcon className="size-4 text-[var(--accent)]" />
              </span>
              <div>
                <p className="text-[11px] font-semibold text-ink">Web protection</p>
                <p className="text-[8.5px] leading-tight text-muted">
                  Phishing, malware, scam, miner and download protection
                </p>
              </div>
            </div>
            <Toggle on />
          </div>
          <p className="mt-2 text-[20px] font-bold leading-none tabular-nums text-ink">
            <span data-d="stopped">0</span>
            <span className="ml-1.5 text-[10px] font-normal text-muted">threats stopped</span>
          </p>
        </div>
        <div>
          <p className="mb-1 text-[10px] font-semibold text-ink">Recently blocked</p>
          <div className="relative">
            <p data-d="recent-empty" className="absolute text-[9.5px] text-muted">
              No threats blocked yet in this session.
            </p>
            <ul className="flex flex-col gap-1">
              {RECENT.map((entry, index) => (
                <li
                  key={entry.host}
                  data-d={`recent-${index}`}
                  className="flex items-center justify-between gap-2 rounded-md border border-line bg-white/[0.03] px-2 py-1 text-[9.5px] opacity-0"
                >
                  <span className="truncate font-medium text-ink">{entry.host}</span>
                  <span className="shrink-0 text-muted">{entry.category}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>
        <div>
          <p className="mb-1 text-[10px] font-semibold text-ink">Trusted sites</p>
          <div className="flex gap-1.5">
            <span
              data-d="trusted-input"
              className="relative flex h-6 min-w-0 flex-1 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[9px] text-ink"
            >
              <span data-d="trusted-text" className="peer truncate" />
              <span className="absolute left-2 hidden text-muted peer-empty:block">
                example.com
              </span>
            </span>
            <span
              data-d="trusted-add"
              className="flex h-6 items-center rounded-md border border-line-strong px-2 text-[9.5px] text-ink-soft"
            >
              Add
            </span>
          </div>
          <div className="relative mt-1.5 h-5">
            <p data-d="trusted-empty" className="absolute text-[9px] leading-tight text-muted">
              No trusted sites. Trusted sites skip list blocking.
            </p>
            <span
              data-d="trusted-chip"
              className="absolute inline-flex items-center gap-1 rounded-full border border-line-strong px-2 py-0.5 text-[9px] text-ink-soft opacity-0"
            >
              {TRUSTED} <XIcon className="size-2.5" />
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}

